// Build-time generator: bundles MDX content into a static TS module so
// dynamic routes (learn-chat, webmcp) can read content in Cloudflare
// Workers, where there is no filesystem at request time. The fs fallback in
// lib/mdx.ts stays for local dev and Vercel.
// Run via the `prebuild` script; the generated file is committed so a
// deploy without prebuild still works.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import matter from "gray-matter";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contentDir = path.join(root, "content");

function walk(dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else if (entry.name.endsWith(".mdx")) out.push(full);
  }
  return out;
}

const titleCase = (s) =>
  s
    .split("-")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");

const bundle = {};

// Learn: key learn/<track>/<file> (full relative path, no .mdx).
for (const file of walk(path.join(contentDir, "learn"))) {
  const rel = path
    .relative(path.join(contentDir, "learn"), file)
    .replace(/\.mdx$/, "")
    .replace(/\\/g, "/");
  const { data, content } = matter(fs.readFileSync(file, "utf8"));
  bundle[`learn/${rel}`] = { content, frontMatter: data };
}

// Blog: flat key blog/<basename> (public URLs are flat).
for (const file of walk(path.join(contentDir, "blog"))) {
  const base = path.basename(file).replace(/\.mdx$/, "");
  const { data, content } = matter(fs.readFileSync(file, "utf8"));
  if (bundle[`blog/${base}`]) console.warn(`duplicate blog slug: ${base}`);
  bundle[`blog/${base}`] = { content, frontMatter: data };
}

// Learn nav structure (mirrors getLearnStructure in lib/mdx.ts).
const structure = [];
for (const track of fs.readdirSync(path.join(contentDir, "learn")).sort()) {
  const trackPath = path.join(contentDir, "learn", track);
  if (!fs.statSync(trackPath).isDirectory()) continue;
  const pages = fs
    .readdirSync(trackPath)
    .filter((f) => f.endsWith(".mdx"))
    .map((file) => {
      const { data } = matter(fs.readFileSync(path.join(trackPath, file), "utf8"));
      return {
        title: String(data.title ?? file),
        slug: `learn/${track}/${file.replace(".mdx", "")}`,
        order: typeof data.order === "number" ? data.order : 0,
      };
    })
    .sort((a, b) => a.order - b.order);
  structure.push({ title: titleCase(track), slug: track, pages });
}

const out =
  `// AUTO-GENERATED by scripts/generate-content-bundle.mjs — do not edit by hand.\n` +
  `// Regenerated on every build via the \`prebuild\` script.\n` +
  `// Lets dynamic routes read MDX content in Cloudflare Workers, where\n` +
  `// there is no filesystem at request time (fs fallback stays for local/Vercel).\n\n` +
  `export const CONTENT_BUNDLE: Record<string, { content: string; frontMatter: Record<string, unknown> }> = ${JSON.stringify(bundle, null, 2)};\n\n` +
  `export const LEARN_STRUCTURE: Array<{ title: string; slug: string; pages: Array<{ title: string; slug: string; order: number }> }> = ${JSON.stringify(structure, null, 2)};\n`;

fs.writeFileSync(path.join(root, "src/lib/content-bundle.generated.ts"), out);
console.log(
  `content-bundle: ${Object.keys(bundle).length} files, ${structure.length} learn tracks`,
);
